BEGIN;

-- Add an empty junction table; no members receive skills during migration.
CREATE TABLE "member_skill" (
    "id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
    "member_id" INTEGER NOT NULL,
    "skill_id" INTEGER NOT NULL,
    CONSTRAINT "member_skill_pkey" PRIMARY KEY ("id"),
    CONSTRAINT "member_skill_member_id_fkey" FOREIGN KEY ("member_id") REFERENCES "member"("member_id") ON DELETE RESTRICT ON UPDATE NO ACTION,
    CONSTRAINT "member_skill_skill_id_fkey" FOREIGN KEY ("skill_id") REFERENCES "skill"("skill_id") ON DELETE RESTRICT ON UPDATE NO ACTION
);

CREATE UNIQUE INDEX "member_skill_member_id_skill_id_key" ON "member_skill"("member_id", "skill_id");
-- The pair index serves member lookup; this index serves lookup by skill.
CREATE INDEX "member_skill_skill_id_idx" ON "member_skill"("skill_id");

COMMIT;
